<?php get_header();rn_page_hero('NEWS','News'); ?><div class="container news-list"><?php $q=new WP_Query(['post_type'=>'post','posts_per_page'=>10,'paged'=>max(1,get_query_var('paged'))]);while($q->have_posts()):$q->the_post(); ?><article><time><?php echo esc_html(get_the_date('Y.m.d')); ?></time><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2></article><?php endwhile;echo wp_kses_post((string)paginate_links(['total'=>$q->max_num_pages]));wp_reset_postdata(); ?></div><?php get_footer(); ?>
